    return pm
tpm=pairmap(target)
def bpd(ss):
    pm=pairmap(ss); d=0
    for i in range(len(ss)):
        if pm[i]!=tpm[i]: d+=1
    return d//2
PAIRS=[('G','C'),('C','G'),('A','U'),('U','A'),('G','U'),('U','G')]
seed='CGAGGCUACAUCCUGGGAUCUUCCCGCUUUCAAGCUAGGAAAAGGACGGACAUCCGAGAGACACUCACCUUAAAUGAUUCACACGAACGUAUGUUAUCUAUCAGUAGCGCACCUUGUACUCGG'

def rand_init():
    seq=['A']*n
    for i in range(n):
        if tpm[i]>i:
            a,b=random.choice(PAIRS); seq[i]=a; seq[tpm[i]]=b
        elif tpm[i]==-1:
            seq[i]=random.choice('ACGU')
    return ''.join(seq)

def mutate(seq, k):
    s=list(seq)
    for _ in range(k):
        i=random.randrange(n)
        if tpm[i]>=0:
            a,b=random.choice(PAIRS); s[i]=a; s[tpm[i]]=b
        else:
            s[i]=random.choice('ACGU')
    return ''.join(s)

def worker(sdict):
    rng=random.Random(sdict)
    # 50% seed from best, 50% random
    if rng.random()<0.5:
        seq=seed
    else:
        seq=rand_init()
    fc=RNA.fold_compound(seq); ss,mfe=fc.mfe(); cur=bpd(ss)
    local_best=(cur,seq,mfe)
    for step in range(600):
        cand=mutate(seq, rng.choice([1,1,2,2,3]))
        fc2=RNA.fold_compound(cand); css,e=fc2.mfe(); d=bpd(css)
        if d<cur or (d==cur and e<mfe):
            seq,ss,cur,mfe=css,css,d,e
